CREATE OR REPLACE FUNCTION public.check_credit_note()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE cid uuid; cn credit_notes; r record; BEGIN
 IF TG_TABLE_NAME='credit_notes' THEN cid:=NEW.id; ELSIF TG_TABLE_NAME='credit_note_items' THEN cid:=COALESCE(NEW.credit_note_id,OLD.credit_note_id); ELSE SELECT credit_note_id INTO cid FROM credit_note_items WHERE id=COALESCE(NEW.credit_note_item_id,OLD.credit_note_item_id); END IF;
 SELECT * INTO cn FROM credit_notes WHERE id=cid;
 IF cn.id IS NULL THEN RETURN NULL; END IF;
 PERFORM 1 FROM invoices WHERE id=cn.invoice_id FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM invoices WHERE id=cn.invoice_id AND lifecycle='issued') THEN RAISE EXCEPTION 'CREDIT_REQUIRES_ISSUED_INVOICE' USING ERRCODE='23514'; END IF;
 IF cn.warranty_claim_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM warranty_claims wc JOIN warranty_entitlements e ON e.id=wc.entitlement_id JOIN order_item_unit_amounts u ON u.id=e.order_item_unit_amount_id JOIN order_items oi ON oi.id=u.order_item_id WHERE wc.id=cn.warranty_claim_id AND oi.order_id=cn.order_id) THEN RAISE EXCEPTION 'WARRANTY_WRONG_ORDER' USING ERRCODE='23514'; END IF;
 IF cn.status='issued' AND cn.total_vnd<>(SELECT COALESCE(sum(amount_vnd),0) FROM credit_note_items WHERE credit_note_id=cid) THEN RAISE EXCEPTION 'CREDIT_TOTAL_MISMATCH' USING ERRCODE='23514'; END IF;
 FOR r IN SELECT cni.*,ii.invoice_id,ii.order_item_id FROM credit_note_items cni JOIN invoice_items ii ON ii.id=cni.invoice_item_id WHERE credit_note_id=cid LOOP
  IF r.invoice_id<>cn.invoice_id THEN RAISE EXCEPTION 'CREDIT_WRONG_INVOICE' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM credit_note_item_units cu JOIN order_item_unit_amounts u ON u.id=cu.order_item_unit_amount_id WHERE cu.credit_note_item_id=r.id AND u.order_item_id<>r.order_item_id) THEN RAISE EXCEPTION 'CREDIT_WRONG_UNIT' USING ERRCODE='23514'; END IF;
  IF cn.status='issued' AND (r.amount_vnd<>(SELECT COALESCE(sum(amount_vnd),0) FROM credit_note_item_units WHERE credit_note_item_id=r.id) OR (r.quantity IS NOT NULL AND r.quantity<>(SELECT count(*) FROM credit_note_item_units WHERE credit_note_item_id=r.id))) THEN RAISE EXCEPTION 'CREDIT_UNITS_MISMATCH' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM credit_note_item_units cu JOIN credit_note_items ci ON ci.id=cu.credit_note_item_id JOIN credit_notes c ON c.id=ci.credit_note_id JOIN order_item_unit_amounts u ON u.id=cu.order_item_unit_amount_id WHERE c.invoice_id=cn.invoice_id GROUP BY u.id HAVING sum(cu.amount_vnd)>u.net_amount_vnd OR count(*)>1) THEN RAISE EXCEPTION 'CREDIT_EXCEEDS_UNIT' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.check_invoice_totals()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE iid uuid; inv invoices; BEGIN
 IF TG_TABLE_NAME='invoices' THEN iid:=COALESCE(NEW.id,OLD.id); ELSE iid:=COALESCE(NEW.invoice_id,OLD.invoice_id); END IF;
 SELECT * INTO inv FROM invoices WHERE id=iid FOR UPDATE;
 IF inv.id IS NULL OR inv.lifecycle='draft' THEN RETURN NULL; END IF;
 IF ROW(inv.subtotal_vnd,inv.discount_total_vnd,inv.grand_total_vnd) IS DISTINCT FROM (SELECT ROW(COALESCE(sum(quantity::bigint*unit_price_vnd),0)::bigint,COALESCE(sum(voucher_discount_vnd+points_discount_vnd),0)::bigint,COALESCE(sum(net_amount_vnd),0)::bigint) FROM invoice_items WHERE invoice_id=iid) OR (SELECT count(*) FROM invoice_items WHERE invoice_id=iid)<>(SELECT count(*) FROM order_items WHERE order_id=inv.order_id) THEN RAISE EXCEPTION 'INVOICE_TOTAL_MISMATCH' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM invoice_items ii JOIN order_items oi ON oi.id=ii.order_item_id LEFT JOIN invoice_items parent ON parent.id=ii.parent_invoice_item_id WHERE ii.invoice_id=iid AND (ROW(ii.quantity,ii.unit_price_vnd,ii.voucher_discount_vnd,ii.points_discount_vnd,ii.net_amount_vnd,ii.line_type,ii.variant_id,ii.product_id) IS DISTINCT FROM ROW(oi.quantity,oi.unit_price_vnd,oi.voucher_discount_vnd,oi.points_discount_vnd,oi.net_amount_vnd,oi.line_type,oi.variant_id,oi.product_id) OR (ii.line_type='warranty' AND (parent.line_type<>'product' OR parent.order_item_id<>oi.parent_item_id)))) THEN RAISE EXCEPTION 'INVOICE_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.check_ledger_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 IF TG_TABLE_NAME='store_credit_entries' THEN
  IF NEW.kind='trade_in' AND NOT EXISTS(SELECT 1 FROM trade_in_quote_items qi JOIN trade_in_items i ON i.id=qi.item_id JOIN trade_in_requests r ON r.id=i.request_id WHERE qi.id=NEW.quote_item_id AND i.id=NEW.trade_in_item_id AND r.customer_id=NEW.user_id AND qi.decision='accepted' AND i.state='completed' AND qi.offered_vnd=NEW.delta_vnd) THEN RAISE EXCEPTION 'TRADE_CREDIT_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
  IF NEW.kind IN ('spend','refund') AND NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND customer_id=NEW.user_id) THEN RAISE EXCEPTION 'CREDIT_LEDGER_WRONG_CUSTOMER' USING ERRCODE='23514'; END IF;
  IF NEW.kind='refund' AND NOT EXISTS(SELECT 1 FROM refunds rf WHERE rf.id=NEW.refund_id AND rf.order_id=NEW.order_id AND rf.status='completed' AND NEW.delta_vnd=(SELECT COALESCE(sum(ra.amount_vnd),0) FROM refund_allocations ra JOIN payment_receipts pr ON pr.id=ra.payment_receipt_id WHERE ra.refund_id=rf.id AND pr.tender_kind='store_credit')) THEN RAISE EXCEPTION 'REFUND_CREDIT_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND customer_id=NEW.user_id) OR (NEW.unit_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM order_item_unit_amounts u JOIN order_items i ON i.id=u.order_item_id WHERE u.id=NEW.unit_id AND i.order_id=NEW.order_id)) THEN RAISE EXCEPTION 'LOYALTY_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 END IF; RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.check_order_totals()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE oid uuid; o orders; r record; n bigint; BEGIN
 IF TG_TABLE_NAME='orders' THEN oid:=NEW.id;
 ELSIF TG_TABLE_NAME='order_items' THEN oid:=COALESCE(NEW.order_id,OLD.order_id);
 ELSE SELECT order_id INTO oid FROM order_items WHERE id=COALESCE(NEW.order_item_id,OLD.order_item_id); END IF;
 SELECT * INTO o FROM orders WHERE id=oid FOR UPDATE;
 IF o.id IS NULL THEN RETURN NULL; END IF;
 IF o.order_status='building' THEN RAISE EXCEPTION 'UNFINISHED_ORDER' USING ERRCODE='23514'; END IF;
 IF o.total_vnd<>(SELECT COALESCE(sum(net_amount_vnd),0) FROM order_items WHERE order_id=oid) OR NOT EXISTS(SELECT 1 FROM order_items WHERE order_id=oid) THEN RAISE EXCEPTION 'ORDER_TOTAL_MISMATCH' USING ERRCODE='23514'; END IF;
 FOR r IN SELECT * FROM order_items WHERE order_id=oid LOOP
  SELECT count(*) INTO n FROM order_item_unit_amounts WHERE order_item_id=r.id;
  IF n<>r.quantity OR EXISTS(SELECT 1 FROM order_item_unit_amounts WHERE order_item_id=r.id AND unit_ordinal>r.quantity) OR ROW(r.quantity::bigint*r.unit_price_vnd,r.voucher_discount_vnd,r.points_discount_vnd,r.net_amount_vnd) IS DISTINCT FROM (SELECT ROW(sum(gross_vnd)::bigint,sum(voucher_discount_vnd)::bigint,sum(points_discount_vnd)::bigint,sum(net_amount_vnd)::bigint) FROM order_item_unit_amounts WHERE order_item_id=r.id) THEN RAISE EXCEPTION 'UNIT_TOTAL_MISMATCH' USING ERRCODE='23514'; END IF;
  IF r.line_type='warranty' AND NOT EXISTS(SELECT 1 FROM order_items p WHERE p.id=r.parent_item_id AND p.line_type='product' AND p.order_id=oid) THEN RAISE EXCEPTION 'CARE_PARENT_INVALID' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM order_item_unit_amounts u LEFT JOIN order_item_unit_amounts pu ON pu.id=u.parent_unit_amount_id WHERE u.order_item_id=r.id AND ((r.line_type='warranty' AND (pu.id IS NULL OR pu.order_item_id<>r.parent_item_id)) OR (r.line_type<>'warranty' AND pu.id IS NOT NULL))) THEN RAISE EXCEPTION 'CARE_UNIT_PARENT_INVALID' USING ERRCODE='23514'; END IF;
 END LOOP; RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.check_refund()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE rid uuid; rf refunds; BEGIN
 IF TG_TABLE_NAME='refunds' THEN rid:=NEW.id; ELSE rid:=NEW.refund_id; END IF;
 SELECT * INTO rf FROM refunds WHERE id=rid;
 PERFORM 1 FROM orders WHERE id=rf.order_id FOR UPDATE;
 IF rf.credit_note_id IS NULL AND EXISTS(SELECT 1 FROM invoices WHERE order_id=rf.order_id AND lifecycle='issued') THEN RAISE EXCEPTION 'REFUND_REQUIRES_CREDIT_NOTE' USING ERRCODE='23514'; END IF;
 IF rf.amount_vnd<>(SELECT COALESCE(sum(amount_vnd),0) FROM refund_allocations WHERE refund_id=rid) THEN RAISE EXCEPTION 'REFUND_TOTAL_MISMATCH' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM refund_allocations ra JOIN payment_receipts pr ON pr.id=ra.payment_receipt_id JOIN order_item_unit_amounts u ON u.id=ra.order_item_unit_amount_id JOIN order_items oi ON oi.id=u.order_item_id WHERE ra.refund_id=rid AND (pr.order_id<>rf.order_id OR oi.order_id<>rf.order_id OR NOT EXISTS(SELECT 1 FROM order_tender_allocations ta WHERE ta.receipt_id=pr.id AND ta.order_item_unit_amount_id=u.id) OR (rf.credit_note_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_note_item_units cu JOIN credit_note_items ci ON ci.id=cu.credit_note_item_id WHERE ci.credit_note_id=rf.credit_note_id AND cu.order_item_unit_amount_id=u.id)))) THEN RAISE EXCEPTION 'REFUND_WRONG_SOURCE' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM refund_allocations ra JOIN refunds r ON r.id=ra.refund_id JOIN order_tender_allocations ta ON ta.receipt_id=ra.payment_receipt_id AND ta.order_item_unit_amount_id=ra.order_item_unit_amount_id WHERE r.order_id=rf.order_id AND r.status<>'failed' GROUP BY ta.id HAVING sum(ra.amount_vnd)>ta.amount_vnd) THEN RAISE EXCEPTION 'REFUND_EXCEEDS_SOURCE' USING ERRCODE='23514'; END IF;
 IF rf.credit_note_id IS NOT NULL AND (SELECT COALESCE(sum(amount_vnd),0) FROM refunds WHERE credit_note_id=rf.credit_note_id AND status<>'failed')>(SELECT total_vnd FROM credit_notes WHERE id=rf.credit_note_id AND status='issued') THEN RAISE EXCEPTION 'REFUND_EXCEEDS_CREDIT' USING ERRCODE='23514'; END IF;
 IF rf.credit_note_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_notes WHERE id=rf.credit_note_id AND status='issued') THEN RAISE EXCEPTION 'REFUND_REQUIRES_ISSUED_CREDIT' USING ERRCODE='23514'; END IF;
 IF rf.credit_note_id IS NULL AND NOT EXISTS(SELECT 1 FROM orders WHERE id=rf.order_id AND order_status IN ('cancelled','reconciliation','expired')) THEN RAISE EXCEPTION 'REFUND_REQUIRES_CANCELLED_UNISSUED_ORDER' USING ERRCODE='23514'; END IF;
 IF rf.credit_note_id IS NOT NULL AND EXISTS(SELECT 1 FROM refund_allocations ra JOIN refunds r ON r.id=ra.refund_id JOIN credit_note_item_units cu ON cu.order_item_unit_amount_id=ra.order_item_unit_amount_id JOIN credit_note_items ci ON ci.id=cu.credit_note_item_id AND ci.credit_note_id=r.credit_note_id WHERE r.credit_note_id=rf.credit_note_id AND r.status<>'failed' GROUP BY cu.credit_note_item_id,cu.order_item_unit_amount_id,cu.amount_vnd HAVING sum(ra.amount_vnd)>cu.amount_vnd) THEN RAISE EXCEPTION 'REFUND_EXCEEDS_CREDIT_UNIT' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.check_tender()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE rid uuid; receipt payment_receipts; BEGIN
 IF TG_TABLE_NAME='payment_receipts' THEN rid:=NEW.id; ELSE rid:=NEW.receipt_id; END IF;
 SELECT * INTO receipt FROM payment_receipts WHERE id=rid;
 PERFORM 1 FROM orders WHERE id=receipt.order_id FOR UPDATE;
 IF receipt.amount_vnd<>(SELECT COALESCE(sum(amount_vnd),0) FROM order_tender_allocations WHERE receipt_id=rid) THEN RAISE EXCEPTION 'RECEIPT_ALLOCATION_MISMATCH' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM order_tender_allocations a JOIN order_item_unit_amounts u ON u.id=a.order_item_unit_amount_id JOIN order_items oi ON oi.id=u.order_item_id WHERE a.receipt_id=rid AND oi.order_id<>receipt.order_id) THEN RAISE EXCEPTION 'TENDER_WRONG_ORDER' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM order_tender_allocations a JOIN payment_receipts pr ON pr.id=a.receipt_id JOIN order_item_unit_amounts u ON u.id=a.order_item_unit_amount_id WHERE pr.order_id=receipt.order_id GROUP BY u.id,pr.tender_kind HAVING sum(a.amount_vnd)>CASE WHEN pr.tender_kind='store_credit' THEN u.credit_planned_vnd ELSE u.cash_planned_vnd END) THEN RAISE EXCEPTION 'TENDER_OVERFUNDED' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.guard_credit_child()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE cid uuid; oldcid uuid; BEGIN
 IF TG_TABLE_NAME='credit_note_items' THEN cid:=CASE WHEN TG_OP='DELETE' THEN OLD.credit_note_id ELSE NEW.credit_note_id END;
 ELSE SELECT credit_note_id INTO cid FROM credit_note_items WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.credit_note_item_id ELSE NEW.credit_note_item_id END; END IF;
 IF TG_OP='UPDATE' THEN IF TG_TABLE_NAME='credit_note_items' THEN oldcid:=OLD.credit_note_id; ELSE SELECT credit_note_id INTO oldcid FROM credit_note_items WHERE id=OLD.credit_note_item_id; END IF; END IF;
 PERFORM 1 FROM credit_notes WHERE id IN(cid,oldcid) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM credit_notes WHERE id IN(cid,oldcid) AND status='issued') THEN RAISE EXCEPTION 'ISSUED_CREDIT_LINES_IMMUTABLE' USING ERRCODE='23514'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.guard_inventory_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'INVENTORY_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='inventory_allocations' THEN
  IF ROW(NEW.id,NEW.order_item_id,NEW.order_item_unit_amount_id,NEW.lot_id,NEW.inventory_unit_id,NEW.quantity,NEW.cost_vnd) IS DISTINCT FROM ROW(OLD.id,OLD.order_item_id,OLD.order_item_unit_amount_id,OLD.lot_id,OLD.inventory_unit_id,OLD.quantity,OLD.cost_vnd) THEN RAISE EXCEPTION 'ALLOCATION_HISTORY_IMMUTABLE' USING ERRCODE='23514'; END IF;
 ELSE
  IF ROW(NEW.id,NEW.warehouse_id,NEW.variant_id,NEW.receipt_item_id,NEW.received_at,NEW.unit_cost_vnd) IS DISTINCT FROM ROW(OLD.id,OLD.warehouse_id,OLD.variant_id,OLD.receipt_item_id,OLD.received_at,OLD.unit_cost_vnd) THEN RAISE EXCEPTION 'LOT_HISTORY_IMMUTABLE' USING ERRCODE='23514'; END IF;
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_inventory_sources()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE qty integer; mode text; BEGIN
 IF TG_TABLE_NAME='inventory_allocations' THEN
  IF NOT EXISTS(SELECT 1 FROM order_items i JOIN inventory_lots l ON l.variant_id=i.variant_id JOIN product_variants v ON v.id=i.variant_id WHERE i.id=NEW.order_item_id AND l.id=NEW.lot_id AND i.line_type='product' AND NEW.quantity=1 AND NEW.cost_vnd=l.unit_cost_vnd AND ((v.tracking_mode='serialized')=(NEW.inventory_unit_id IS NOT NULL))) THEN RAISE EXCEPTION 'ALLOCATION_SKU_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='inventory_reservations' THEN
  IF NOT EXISTS(SELECT 1 FROM order_items WHERE id=NEW.order_item_id AND variant_id=NEW.variant_id AND quantity=NEW.quantity AND line_type='product') THEN RAISE EXCEPTION 'RESERVATION_SKU_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='goods_receipt_items' THEN
  PERFORM 1 FROM purchase_order_items WHERE id=NEW.purchase_order_item_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM purchase_order_items WHERE id=NEW.purchase_order_item_id AND unit_cost_vnd=NEW.unit_cost_vnd) OR (SELECT COALESCE(sum(received_qty),0) FROM goods_receipt_items WHERE purchase_order_item_id=NEW.purchase_order_item_id AND id<>NEW.id)+NEW.received_qty>(SELECT quantity FROM purchase_order_items WHERE id=NEW.purchase_order_item_id) THEN RAISE EXCEPTION 'GOODS_RECEIPT_SOURCE_OR_QUANTITY' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='inventory_lots' THEN
  IF NOT EXISTS(SELECT 1 FROM goods_receipt_items ri JOIN purchase_order_items pi ON pi.id=ri.purchase_order_item_id WHERE ri.id=NEW.receipt_item_id AND pi.variant_id=NEW.variant_id AND ri.unit_cost_vnd=NEW.unit_cost_vnd) THEN RAISE EXCEPTION 'LOT_SKU_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_invoice_item()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE parent invoices; BEGIN
 SELECT * INTO parent FROM invoices WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END FOR UPDATE;
 IF parent.lifecycle='issued' OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM invoices WHERE id=OLD.invoice_id AND lifecycle='issued')) THEN RAISE EXCEPTION 'ISSUED_LINES_IMMUTABLE' USING ERRCODE='23514'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.guard_order_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE oid uuid; oldoid uuid; BEGIN
 IF TG_TABLE_NAME='order_items' THEN oid:=CASE WHEN TG_OP='DELETE' THEN OLD.order_id ELSE NEW.order_id END; IF TG_OP='UPDATE' THEN oldoid:=OLD.order_id; END IF;
 ELSE SELECT order_id INTO oid FROM order_items WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.order_item_id ELSE NEW.order_item_id END; IF TG_OP='UPDATE' THEN SELECT order_id INTO oldoid FROM order_items WHERE id=OLD.order_item_id; END IF; END IF;
 PERFORM 1 FROM orders WHERE id=oid FOR UPDATE;
 IF EXISTS(SELECT 1 FROM orders WHERE id IN (oid,oldoid) AND order_status<>'building') THEN RAISE EXCEPTION 'ORDER_SNAPSHOT_IMMUTABLE' USING ERRCODE='23514'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.guard_trade_quote_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'TRADE_QUOTE_HISTORY_IMMUTABLE' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='trade_in_quotes' THEN
  IF ROW(NEW.id,NEW.request_id,NEW.version_no,NEW.expires_at,NEW.quoted_by) IS DISTINCT FROM ROW(OLD.id,OLD.request_id,OLD.version_no,OLD.expires_at,OLD.quoted_by) OR (OLD.approved_by IS NOT NULL AND NEW.approved_by IS DISTINCT FROM OLD.approved_by) THEN RAISE EXCEPTION 'TRADE_QUOTE_HISTORY_IMMUTABLE' USING ERRCODE='23514'; END IF;
 ELSE
  IF ROW(NEW.id,NEW.quote_id,NEW.request_id,NEW.item_id,NEW.offered_vnd) IS DISTINCT FROM ROW(OLD.id,OLD.quote_id,OLD.request_id,OLD.item_id,OLD.offered_vnd) OR (OLD.decision<>'pending' AND ROW(NEW.decision,NEW.decided_at) IS DISTINCT FROM ROW(OLD.decision,OLD.decided_at)) THEN RAISE EXCEPTION 'TRADE_QUOTE_ITEM_IMMUTABLE' USING ERRCODE='23514'; END IF;
  IF NEW.decision<>'pending' AND NEW.decided_at IS NULL THEN RAISE EXCEPTION 'TRADE_DECISION_REQUIRES_TIME' USING ERRCODE='23514'; END IF;
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_warranty_replacement_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE original uuid; variant uuid; oldvariant uuid; newvariant uuid; mode text; BEGIN
 SELECT e.order_item_unit_amount_id,i.variant_id,v.tracking_mode INTO original,variant,mode FROM warranty_claims c JOIN warranty_entitlements e ON e.id=c.entitlement_id JOIN order_item_unit_amounts u ON u.id=e.order_item_unit_amount_id JOIN order_items i ON i.id=u.order_item_id JOIN product_variants v ON v.id=i.variant_id WHERE c.id=NEW.claim_id;
 IF original IS NULL OR (NEW.order_item_unit_amount_id IS NOT NULL AND NEW.order_item_unit_amount_id<>original) THEN RAISE EXCEPTION 'REPLACEMENT_WRONG_ENTITLEMENT' USING ERRCODE='23514'; END IF; NEW.order_item_unit_amount_id:=original;
 IF mode='serialized' THEN
  SELECT l.variant_id INTO oldvariant FROM inventory_units u JOIN inventory_lots l ON l.id=u.lot_id WHERE u.id=NEW.old_unit_id;
  SELECT l.variant_id INTO newvariant FROM inventory_units u JOIN inventory_lots l ON l.id=u.lot_id WHERE u.id=NEW.new_unit_id;
  IF NOT EXISTS(SELECT 1 FROM warranty_claims c JOIN warranty_entitlements e ON e.id=c.entitlement_id WHERE c.id=NEW.claim_id AND e.inventory_unit_id=NEW.old_unit_id) THEN RAISE EXCEPTION 'REPLACEMENT_WRONG_OLD_SERIAL' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT variant_id INTO oldvariant FROM inventory_lots WHERE id=NEW.old_lot_id; SELECT variant_id INTO newvariant FROM inventory_lots WHERE id=NEW.new_lot_id;
  IF NOT EXISTS(SELECT 1 FROM inventory_allocations WHERE order_item_unit_amount_id=original AND lot_id=NEW.old_lot_id AND state IN ('shipped','returned','replaced')) THEN RAISE EXCEPTION 'REPLACEMENT_WRONG_OLD_LOT' USING ERRCODE='23514'; END IF;
 END IF;
 IF oldvariant IS DISTINCT FROM variant OR newvariant IS DISTINCT FROM variant THEN RAISE EXCEPTION 'REPLACEMENT_REQUIRES_SAME_SKU' USING ERRCODE='23514'; END IF; RETURN NEW;
END $function$
